import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

public BigDecimal total(BigDecimal subtotal) {
    return subtotal;
}

public java.util.List<BigDecimal> splitEvenly(BigDecimal total, int parts) {
    if (parts <= 0) {
        throw new IllegalArgumentException("parts must be > 0");
    }
    long totalCents = total.movePointRight(2).longValueExact();
    long base = Math.floorDiv(totalCents, parts);
    int remainder = (int) Math.floorMod(totalCents, parts);
    List<BigDecimal> result = new ArrayList<>(parts);
    for (int i = 0; i < parts; i++) {
        long shareCents = (i < remainder) ? base + 1 : base;
        result.add(BigDecimal.valueOf(shareCents).movePointLeft(2).setScale(2));
    }
    return result;
}

